/**
 * FlowDetail shows the flow's client connection ID (`conn_id`) and links to
 * the Flows list filtered to that connection, so the other h2 streams
 * multiplexed on it (or HTTP/1.x keep-alive requests) are one click away.
 *
 * The data hooks are mocked and the page is rendered with
 * renderToStaticMarkup inside a MemoryRouter, as in
 * FlowDetailPage.messagesQuery.test.tsx. Fixtures are real
 * `query resource=flow` responses generated by
 * internal/mcp/webui_http_fixture_test.go; none of them carries conn_info,
 * so they also pin that the link does not depend on it.
 */

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { beforeEach, describe, expect, it, vi } from "vitest";
import type { FlowDetailResult } from "../../lib/mcp/types.js";
import h1Text from "./__fixtures__/h1-flow.response.json?raw";
import h2Text from "./__fixtures__/h2-flow.response.json?raw";

const mockState = vi.hoisted(() => ({
  flow: null as unknown,
}));

vi.mock("../../lib/mcp/hooks.js", () => ({
  useQuery: (resource: string) => ({
    data: resource === "flow" ? mockState.flow : null,
    loading: false,
    error: null,
    refetch: () => {},
  }),
  useManage: () => ({ manage: async () => ({}), loading: false }),
}));

vi.mock("../../components/ui/toastContext.js", () => ({
  useToast: () => ({ addToast: () => {} }),
}));

vi.mock("../../components/ui/dialogContext.js", () => ({
  useDialog: () => ({ showDialog: async () => false }),
}));

// Import after the mocks are registered so the page resolves the stubs.
const { FlowDetailPage } = await import("./FlowDetailPage.js");

const h1 = JSON.parse(h1Text) as FlowDetailResult;
const h2 = JSON.parse(h2Text) as FlowDetailResult;

function render(flow: FlowDetailResult): string {
  mockState.flow = flow;
  return renderToStaticMarkup(
    createElement(
      MemoryRouter,
      { initialEntries: [`/flows/${flow.id}`] },
      createElement(
        Routes,
        null,
        createElement(Route, {
          path: "/flows/:id",
          element: createElement(FlowDetailPage),
        }),
      ),
    ),
  );
}

beforeEach(() => {
  mockState.flow = null;
});

describe("FlowDetailPage connection link", () => {
  it("fixtures carry a conn_id and no conn_info", () => {
    expect(h2.conn_id).toBe("conn-stream-http-h2");
    expect(h1.conn_id).toBe("conn-stream-http-h1");
    expect(h2.conn_info).toBeUndefined();
    expect(h1.conn_info).toBeUndefined();
  });

  it.each([
    ["h2", h2],
    ["h1", h1],
  ])("shows the conn_id and links to the flows on that connection (%s)", (_name, flow) => {
    const html = render(flow);
    expect(html).toContain(">Connection<");
    expect(html).toContain(`>${flow.conn_id}<`);
    expect(html).toContain(`href="/?conn_id=${flow.conn_id}"`);
    expect(html).toContain("Flows on this connection");
  });

  it("URL-encodes the conn_id in the link", () => {
    // Imported JSONL can carry arbitrary conn_id strings.
    const html = render({ ...h2, conn_id: "a b&c=d" });
    expect(html).toContain(`href="/?conn_id=a+b%26c%3Dd"`);
  });

  it("shows no connection link when the flow has no conn_id", () => {
    // resend_http / fuzz_http record streams with an empty conn_id: their
    // Send envelopes come from http1.BuildSendEnvelope, which sets no
    // EnvelopeContext. An empty filter.conn_id would list every flow.
    const withLink = render(h2);
    expect(withLink).toContain("Flows on this connection");
    const html = render({ ...h2, conn_id: "" });
    expect(html).not.toContain("Flows on this connection");
    expect(html).not.toContain("conn_id=");
  });
});
